{
  "name": "USBTMC 通信组件",
  "name_en": "USBTMC Communication Component",
  "manufacturer": "",
  "description": "用于通过 USB Test and Measurement Class（USBTMC）协议与实验仪器通信的软件组件，并非具体物理设备。它负责封装与解析 USBTMC 报文、发送命令、接收响应以及管理底层 USB 文本通信，适合连接支持 USBTMC 的测试测量仪器。",
  "description_en": "A software component for communicating with laboratory instruments over the USB Test and Measurement Class (USBTMC) protocol, rather than a specific physical device. It handles USBTMC message construction and parsing, command transmission, response reception, and low-level USB text communication for instruments that support USBTMC.",
  "actions": [
    {
      "action_name": "auto-finalize",
      "description": "结束并清理 USBTMC 通信会话。",
      "description_en": "Finalize and clean up the USBTMC communication session."
    },
    {
      "action_name": "auto-raw_recv",
      "description": "从 USBTMC 连接原始接收字节数据。",
      "description_en": "Receive raw byte data from the USBTMC connection."
    },
    {
      "action_name": "auto-raw_send",
      "description": "向 USBTMC 连接原始发送字节数据。",
      "description_en": "Send raw byte data over the USBTMC connection."
    },
    {
      "action_name": "auto-recv",
      "description": "接收 USBTMC 设备返回的响应数据。",
      "description_en": "Receive response data returned by the USBTMC device."
    },
    {
      "action_name": "auto-send",
      "description": "向 USBTMC 设备发送命令或文本数据。",
      "description_en": "Send commands or text data to the USBTMC device."
    },
    {
      "action_name": "auto-build_array",
      "description": "构建用于 USBTMC 传输的字节数组或报文数据。",
      "description_en": "Build a byte array or message payload for USBTMC transfer."
    },
    {
      "action_name": "auto-from_bytes",
      "description": "从原始字节数据解析 USBTMC 报文对象。",
      "description_en": "Parse a USBTMC message object from raw byte data."
    }
  ],
  "tag_hints": [
    "USBTMC",
    "USB instrument communication",
    "SCPI transport",
    "test and measurement protocol",
    "bulk IN/OUT transfer",
    "message parsing",
    "laboratory instrument control"
  ]
}

